ALL.sql:
SELECT name, age
FROM students
WHERE age > ALL (SELECT age FROM students WHERE city = 'Berlin');

AND.sql:
SELECT name, age, city
FROM students
WHERE age > 19 AND city = 'Berlin';

ANY.sql:
SELECT name, age
FROM students
WHERE age > ALL (SELECT age FROM students WHERE city = 'Berlin');

ASC.sql:
SELECT name, age
FROM students
ORDER BY age DESC;

BETWEEN.sql:
SELECT name, age
FROM students
WHERE age BETWEEN 20 AND 22;

CASE.sql:
SELECT name, age,
       CASE WHEN age < 21 THEN 'young' ELSE 'adult' END AS age_group
FROM students;

CHECK.sql:
CREATE TABLE t2 (age integer CHECK (age BETWEEN 0 AND 120));
INSERT INTO t2 VALUES (30);
SELECT * FROM t2;

CREATE INDEX.sql:
CREATE INDEX idx_students_city ON students (city);
SELECT indexname FROM pg_indexes
WHERE schemaname = current_schema() AND tablename = 'students'
ORDER BY indexname;

CREATE TABLE.sql:
CREATE TABLE pets (
    id integer PRIMARY KEY,
    name varchar NOT NULL
);
INSERT INTO pets VALUES (1, 'Rex');
SELECT * FROM pets;

CREATE TRIGGER.sql:
CREATE TABLE log_t (msg varchar);
CREATE FUNCTION fn_log() RETURNS trigger AS $$ BEGIN INSERT INTO log_t VALUES ('added ' || NEW.title); RETURN NEW; END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_log AFTER INSERT ON courses FOR EACH ROW EXECUTE FUNCTION fn_log();
INSERT INTO courses VALUES (20, 'Chess');
SELECT * FROM log_t;

CREATE VIEW.sql:
CREATE VIEW young_students AS
SELECT name, age FROM students WHERE age < 21;
SELECT * FROM young_students;

CTE.sql:
WITH adults AS (
    SELECT name, age FROM students WHERE age >= 21
)
SELECT name FROM adults
ORDER BY name;

DEFAULT.sql:
CREATE TABLE t4 (id integer, status varchar DEFAULT 'new');
INSERT INTO t4 (id) VALUES (1);
SELECT * FROM t4;

DELETE.sql:
DELETE FROM sales
WHERE shop = 'East'
RETURNING *;

DENSE_RANK.sql:
SELECT item, qty, RANK() OVER (ORDER BY qty DESC) AS rnk, DENSE_RANK() OVER (ORDER BY qty DESC) AS dense_rnk
FROM sales
ORDER BY qty DESC, id;

DESC.sql:
SELECT name, age
FROM students
ORDER BY age DESC;

DROP.sql:
CREATE VIEW tmp_view AS SELECT 1 AS x;
DROP VIEW tmp_view;
SELECT COUNT(*) AS views_left FROM pg_views WHERE schemaname = current_schema() AND viewname = 'tmp_view';

EXISTS.sql:
SELECT name
FROM students
WHERE EXISTS (
    SELECT 1 FROM courses
    WHERE courses.id = students.course_id
);

FOREIGN KEY.sql:
SELECT conname, contype
FROM pg_constraint
WHERE conrelid = 'students'::regclass AND contype = 'f';

ILIKE.sql:
SELECT name
FROM students
WHERE name ILIKE 'a%';

IN.sql:
SELECT name, city
FROM students
WHERE city IN ('Paris', 'Rome');

