LAG.sql:
SELECT sale_date, qty, LAG(qty) OVER (ORDER BY sale_date, id) AS previous_qty
FROM sales
ORDER BY sale_date, id;

LEAD.sql:
SELECT sale_date, qty, LAG(qty) OVER (ORDER BY sale_date, id) AS previous_qty
FROM sales
ORDER BY sale_date, id;

LIKE.sql:
